}

export interface MessageInput {
  text: string;
  maxLength?: number;
}

const DEFAULT_MAX_LENGTH = 500;

// Trim leading/trailing whitespace before applying the length cap.
export function formatMessage({ text, maxLength = DEFAULT_MAX_LENGTH }: MessageInput): string {
  const trimmed = text.trimStart().trimEnd();
  if (trimmed.length <= maxLength) {
    return trimmed;
  }
  return `${trimmed.slice(0, maxLength - 1)}\u2026`;
}

export interface MessageInput {
  text: string;
  maxLength?: number;
}

const DEFAULT_MAX_LENGTH = 500;

export function formatMessage({ text, maxLength = DEFAULT_MAX_LENGTH }: MessageInput): string {
  const trimmed = text.trim();
  const segmenter = new Intl.Segmenter();
  const segments = [...segmenter.segment(trimmed)];
  if (segments.length <= maxLength) {
    return trimmed;
  }
  return segments.slice(0, maxLength - 1).map((s) => s.segment).join('') + '\u2026';
}

import { LitElement, html } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import { formatMessage } from '../../utils/format-message';

@customElement('example-message-list')
export class MessageList extends LitElement {
  @property({ type: Array })
  messages: string[] = [];

  @property({ type: Boolean })
  scrollable = false;

  @property({ type: String })
  emptyText = 'No messages yet.';

  @property({ type: Boolean })
  reversed = false;

  @property({ type: String })
  highlightQuery = '';

  private readonly onResize = () => this.requestUpdate();

  connectedCallback() {
    super.connectedCallback();
    window.addEventListener('resize', this.onResize);
  }

  disconnectedCallback() {
    window.removeEventListener('resize', this.onResize);
    super.disconnectedCallback();
  }

  private getDisplayMessages(): string[] {
    return this.reversed ? [...this.messages].reverse() : this.messages;
  }

  private highlightText(text: string): string {
    if (!this.highlightQuery) return text;
    return text.replace(
      new RegExp(this.highlightQuery, 'gi'),
      (match) => `<mark>${match}</mark>`
    );
  }

  render() {
    const items = this.getDisplayMessages();
    if (items.length === 0) {
      return html`<p class="empty">${this.emptyText}</p>`;
    }
    return html`<ul role="list" class=${this.scrollable ? 'scrollable' : ''}>
      ${items.map(
        (message) =>
          html`<li .innerHTML=${this.highlightText(formatMessage({ text: message }))}></li>`
      )}
    </ul>`;
  }
}

